import java.util.*; class Solution { record Item(String id,String name){Item{if(id.isBlank()||name.isBlank())throw new IllegalArgumentException("item");}} static class ViewModel { private final Map<String,Item> items=new LinkedHashMap<>(); void save(String id,String name){Item item=new Item(id.trim(),name.trim());items.put(item.id(),item);} Optional<Item> selected(String id){return Optional.ofNullable(items.get(id));} List<Item> rows(){return List.copyOf(items.values());} void delete(String id){items.remove(id);} } }
